"""Names are facts shared by every consumer, never generated by a view."""
import re
from dataclasses import replace
from datetime import datetime, timezone
from pathlib import Path
from types import SimpleNamespace

import pytest

from jrbar.collector import _merged_status_candidates
from jrbar.core_projection import project_session_rows, session_label
from jrbar.models import AgentMode, AgentStatus, ParentLink
from jrbar.project_names import project_name, repository_project

NOW = datetime(2026, 10, 7, 12, tzinfo=timezone.utc)
BAD = re.compile(r"\b[0-9a-fA-F]{8,}\b|^t3-|^session$|/worktrees/", re.I)


@pytest.mark.parametrize("provider", ["codex", "claude", "factory", "devin", "t3code"])
@pytest.mark.parametrize("label", [None, "Session", "t3-", "t3-deadbeef", "Codex deadbeef", "deadbeef"])
def test_fallback_never_names_a_session_by_an_identifier(provider, label):
    name = session_label(provider=provider, session_id="deadbeef-0000-4000-8000-000000000000",
                         agent_id=f"{provider}:session:deadbeef", display_name=label,
                         cwd="/synthetic/.t3/worktrees/Sample/t3-cafebabe", extras=None)
    assert name == f"{'T3 Code' if provider == 't3code' else provider.title()} session in Sample"
    assert not BAD.search(name)


def test_titles_survive_a_newer_hook_and_an_ended_head():
    head = AgentStatus("claude", "claude:session:head", "Session", AgentMode.COMPLETED, NOW, "Stop",
                       session_id="head", session_title="Improve the panel", project="Sample")
    child = AgentStatus("codex", "codex:session:child", "t3-", AgentMode.WORKING, NOW, "PreToolUse",
                        session_id="child", cwd="/synthetic/.t3/worktrees/Sample/t3-cafebabe")
    task = replace(child, event_name="LineageObserved", session_title="Install the sample build",
                   origin="T3 Code", parent_links=(ParentLink(child.agent_id, head.agent_id, "t3code", NOW.timestamp()),))
    statuses = _merged_status_candidates([head, child, task])
    named = {status.agent_id: status for status in statuses}
    assert named[child.agent_id].display_name == "Install the sample build"
    assert named[child.agent_id].mode is AgentMode.WORKING
    rows, _ = project_session_rows(SimpleNamespace(statuses=statuses, stale_statuses=(), collected_at=NOW))
    assert {row["id"]: row["label"] for row in rows} == {status.agent_id: status.display_name for status in statuses}
    assert next(row for row in rows if row["id"] == child.agent_id)["project"] == "Sample"


def test_project_names_fold_t3_claude_and_arbitrary_git_worktrees(tmp_path):
    assert project_name("/synthetic/.t3/worktrees/Sample/t3-cafebabe/src") == "Sample"
    assert project_name("/synthetic/Sample/.claude/worktrees/worker/src") == "Sample"
    assert project_name("/synthetic/Sample/.worktrees/worker") == "Sample"
    root = tmp_path / "Sample"
    git = root / ".git"
    admin = git / "worktrees" / "arbitrary-worker"
    admin.mkdir(parents=True)
    (admin / "commondir").write_text("../..")
    worktree = tmp_path / "arbitrary-worker"
    worktree.mkdir()
    (worktree / ".git").write_text(f"gitdir: {admin}")
    assert repository_project(str(worktree)) == "Sample"
    assert repository_project(str(worktree / "src")) == "Sample"
    assert repository_project(str(root)) == "Sample"


def test_views_do_not_compose_session_names():
    root = Path(__file__).resolve().parents[1]
    violations = []
    for path in (root / "app/Sources/JRBarApp").rglob("*.swift"):
        if ": View" not in path.read_text() and "View" not in path.name:
            continue
        for number, line in enumerate(path.read_text().splitlines(), 1):
            if re.search(r"\b(?:session|asking|entry\.session)\.(?:label|shortId)\b|SessionLabel\.display\(|Text\([^\n]*\\\([^\n]*\.style\.name[^\n]*\.label", line):
                violations.append(f"{path.name}:{number}: use CoreSession.displayLabel")
    assert not violations, "\n".join(violations)


def test_untitled_sessions_use_their_recorded_start_when_names_collide():
    from jrbar.core_projection import session_names
    first = AgentStatus('codex', 'codex:session:first', 'Session', AgentMode.WORKING, NOW, 'SessionStart',
                        cwd='/synthetic/Sample', started_at=NOW.timestamp() - 600)
    second = replace(first, agent_id='codex:session:second', started_at=NOW.timestamp())
    names = session_names([first, second])
    assert names[first.agent_id] != names[second.agent_id]
    assert all(name.startswith('Codex session in Sample at ') and not BAD.search(name) for name in names.values())


@pytest.mark.parametrize('provider', ['codex', 'claude', 'factory', 'devin', 't3code'])
def test_deck_and_speech_use_the_shared_fallback(provider):
    from jrbar.announcer_stack import _label_for
    from jrbar.deck_session_board import DeckSessionBoard
    from jrbar.provider_facts import SourceKey, WorkIdentifier, WorkKey
    status = AgentStatus(provider, f'{provider}:session:deadbeef', 't3-', AgentMode.WORKING, NOW, 'PreToolUse',
                         session_id='deadbeef', cwd='/synthetic/.t3/worktrees/Sample/t3-cafebabe',
                         work_key=WorkKey(SourceKey(provider, 'native', 'synthetic', 'threads'), WorkIdentifier('deadbeef')))
    board = DeckSessionBoard(clock=lambda: NOW)
    board.update([status])
    label = board.snapshot().slots[0].title
    expected = session_label(provider=provider, session_id=status.session_id, agent_id=status.agent_id,
                             display_name=status.display_name, cwd=status.cwd, extras=None)
    assert label == expected
    assert not BAD.search(label)
    row = SimpleNamespace(display_name=status.display_name, agent_id=status.agent_id, source_status=status)
    assert _label_for(row, None, provider) == expected


def test_readable_native_ids_are_not_mistaken_for_provider_titles():
    assert session_label(provider='codex', session_id='work:offline', agent_id='codex:session:work:offline',
                         display_name='Codex work:offline', cwd='/synthetic/Sample', extras=None) == 'Codex session in Sample'


def test_a_submodule_without_a_commondir_keeps_its_repository_name(tmp_path):
    root = tmp_path / 'Parent'
    module = root / 'Child'
    module.mkdir(parents=True)
    (root / '.git' / 'modules' / 'Child').mkdir(parents=True)
    (module / '.git').write_text('gitdir: ../.git/modules/Child')
    assert repository_project(str(module)) == 'Child'
